// 2. Funzione helper per calcolare l'aggregazione in JavaScript
function calculateAggregation(points, type) {
    if (!points || points.length === 0) return null;

    let sum = 0, min = Infinity, max = -Infinity;
    const count = points.length;

    for (let i = 0; i < count; i++) {
        // I punti di Redis TS sono formattati come [timestamp, value]
        // Il value potrebbe essere una stringa, lo forziamo a float
        let val = parseFloat(points[i][1]); 
        sum += val;
        if (val < min) min = val;
        if (val > max) max = val;
    }

    switch ((type || 'avg').toLowerCase()) {
        case 'avg': return sum / count;
        case 'sum': return sum;
        case 'min': return min;
        case 'max': return max;
        case 'count': return count;
        case 'first': return parseFloat(points[0][1]);
        case 'last': return parseFloat(points[count - 1][1]);
        default: return sum / count; // default fallback a 'avg'
    }
}

// 3. Processamento dei dati TimeSeries
const aggregations = {};

if (rawTsResults) {
    for (let item of rawTsResults) {
        const paramName = item[0];
        const tsData = item[1]; // Dati grezzi estratti da TS.MRANGE
        const aggType = item[2]; // avg, sum, min, etc... fornito da Lua

        let allPoints = [];

        // TS.MRANGE restituisce un array di serie che matchano i filtri
        // Struttura: [ [nome_chiave, labels, [punti]], ... ]
        if (Array.isArray(tsData)) {
            for (let series of tsData) {
                // series[2] contiene l'array dei punti [timestamp, value]
                if (series && Array.isArray(series[2])) {
                    allPoints.push(...series[2]);
                }
            }
        }

        // Ordiniamo i punti cronologicamente (essenziale per 'first' o 'last')
        allPoints.sort((a, b) => a[0] - b[0]);

        // Calcoliamo e salviamo il risultato
        aggregations[paramName] = calculateAggregation(allPoints, aggType);
    }
}

