// CONFIGURAZIONE DEL NODO (Modifica questi valori secondo necessità)
var config = {
    intervalCount: 10,           // Numero di intervalli
    intervalUnits: "s",         // "s" (secondi), "m" (minuti), "h" (ore), "d" (giorni)
    submitPerTopic: true,       // true: invia un msg separato per ogni topic, false: singolo payload
    submitIncompleteInterval: false,
    aggregationType: "mean",    // Strategia di fallback se msg.strategy non c'è
    topic: "aggregated"         // Topic usato solo se submitPerTopic è false
};

context.set("config", config);
context.set("values", {});

var factor = 1;
switch (config.intervalUnits) {
    case "s": factor = 1000; break;
    case "m": factor = 1000 * 60; break;
    case "h": factor = 1000 * 60 * 60; break;
    case "d": factor = 1000 * 60 * 60 * 24; break;
}

var intervalTimeout = factor * config.intervalCount;
var absoluteStartupTime = new Date();
absoluteStartupTime.setMinutes(absoluteStartupTime.getMinutes() - absoluteStartupTime.getTimezoneOffset());
var correctedStartupTime = absoluteStartupTime.getTime();
var startupTimeout = intervalTimeout - (correctedStartupTime % intervalTimeout);

function aggregate(list, strategy) {
    if (!list || list.length === 0) return null;
    var aggType = strategy || config.aggregationType;

    switch (aggType) {
        case "mean": return simpleStatistics.mean(list);
        case "geometricMean": return simpleStatistics.geometricMean(list);
        case "harmonicMean": return simpleStatistics.harmonicMean(list);
        case "median": return simpleStatistics.median(list);
        case "min": return simpleStatistics.min(list);
        case "max": return simpleStatistics.max(list);
        case "sum": return simpleStatistics.sumSimple(list);
        default: return list[list.length - 1]; // Fallback
    }
}

function aggregateAll() {
    var values = context.get("values") || {};
    var results = [];
    var lastGlobalStrategy = config.aggregationType;
    var messagesToSend = [];

    if (config.submitPerTopic) {
        for (var topic in values) {
            if (values.hasOwnProperty(topic)) {
                var topicData = values[topic];
                var payloads = topicData.payloads;
                var strategy = topicData.strategy;

                if (payloads.length > 0) {
                    var finalPayload;

                    if (typeof payloads[0] === 'object' && !Array.isArray(payloads[0]) && payloads[0] !== null) {
                        finalPayload = {};
                        var keys = Object.keys(payloads[0]);

                        keys.forEach(function (key) {
                            var list = payloads.map(function (p) { return parseFloat(p[key]); }).filter(function (v) { return !isNaN(v); });

                            // Assegnazione sicura per il linter
                            var attrStrategy = strategy;
                            if (strategy && typeof strategy === 'object') {
                                attrStrategy = strategy[key];
                            }

                            finalPayload[key] = aggregate(list, attrStrategy);
                        });
                    } else {
                        var list = payloads.map(function (p) { return parseFloat(p); }).filter(function (v) { return !isNaN(v); });
                        finalPayload = aggregate(list, strategy);
                    }

                    messagesToSend.push({ topic: topic, payload: finalPayload });
                }
            }
        }
    } else {
        for (var topic in values) {
            if (values.hasOwnProperty(topic)) {
                var topicData = values[topic];
                var payloads = topicData.payloads;
                var strategy = topicData.strategy;

                // Aggiorniamo la strategia globale se esiste
                if (strategy) {
                    lastGlobalStrategy = strategy;
                }

                if (payloads.length > 0) {
                    if (typeof payloads[0] === 'object' && !Array.isArray(payloads[0]) && payloads[0] !== null) {
                        var aggregatedObj = {};
                        var keys = Object.keys(payloads[0]);
                        keys.forEach(function (key) {
                            var list = payloads.map(function (p) { return parseFloat(p[key]); }).filter(function (v) { return !isNaN(v); });

                            // Assegnazione sicura per il linter
                            var attrStrategy = strategy;
                            if (strategy && typeof strategy === 'object') {
                                attrStrategy = strategy[key];
                            }

                            aggregatedObj[key] = aggregate(list, attrStrategy);
                        });
                        results.push(aggregatedObj);
                    } else {
                        var list = payloads.map(function (p) { return parseFloat(p); }).filter(function (v) { return !isNaN(v); });
                        results.push(aggregate(list, strategy));
                    }
                }
            }
        }

        if (results.length > 0) {
            var finalPayload;
            if (typeof results[0] === 'object' && !Array.isArray(results[0]) && results[0] !== null) {
                finalPayload = {};
                var keys = Object.keys(results[0]);
                keys.forEach(function (key) {
                    var list = results.map(function (p) { return parseFloat(p[key]); }).filter(function (v) { return !isNaN(v); });

                    // Assegnazione sicura della lastGlobalStrategy
                    var attrStrategy = lastGlobalStrategy;
                    if (lastGlobalStrategy && typeof lastGlobalStrategy === 'object') {
                        // @ts-ignore
                        attrStrategy = lastGlobalStrategy[key];
                    }

                    finalPayload[key] = aggregate(list, attrStrategy);
                });
            } else {
                finalPayload = aggregate(results, lastGlobalStrategy);
            }

            messagesToSend.push({ topic: config.topic || "", payload: finalPayload });
        }
    }

    // Invia i messaggi
    messagesToSend.forEach(function (m) {
        node.send(m);
    });

    // Svuota la memoria dopo l'invio
    context.set("values", {});
}

// Avvia i timer
var primaryTimeout = setTimeout(function () {
    var intervalId = setInterval(aggregateAll, intervalTimeout);
    context.set("intervalId", intervalId);

    if (config.submitIncompleteInterval) {
        aggregateAll();
    } else {
        context.set("values", {});
    }
}, startupTimeout);

context.set("primaryTimeoutId", primaryTimeout);

